export const DEFAULT_BINDINGS={forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD',fire:'Mouse0',dash:'Space',orbitLeft:'KeyQ',orbitRight:'KeyE',orbitDrag:'Mouse2',pause:'KeyP',weapon1:'Digit1',weapon2:'Digit2',weapon3:'Digit3',weapon4:'Digit4',weapon5:'Digit5'};
export const ACTION_LABELS={forward:'Move forward',back:'Move backward',left:'Move left',right:'Move right',fire:'Fire',dash:'Phase dash',orbitLeft:'Orbit left',orbitRight:'Orbit right',orbitDrag:'Drag camera',pause:'Pause / resume',weapon1:'Assault rifle',weapon2:'Stinger SMG',weapon3:'Scatter shotgun',weapon4:'Lancer railgun',weapon5:'Havoc launcher'};
export function keyLabel(code){return ({Mouse0:'Left mouse',Mouse1:'Middle mouse',Mouse2:'Right mouse',Space:'Space',Escape:'Esc'})[code]||code.replace(/^Key|^Digit/,'').replace('Arrow','Arrow ')}
export function loadPreferences(storage){let p={};try{p=JSON.parse(storage?.getItem?.('neon-crypt-preferences-v1')||'{}')||{}}catch{}const bindings={...DEFAULT_BINDINGS};if(p.bindings&&Object.keys(bindings).every(k=>typeof p.bindings[k]==='string'&&/^(Key[A-Z]|Digit[0-9]|Arrow(Up|Down|Left|Right)|Space|ShiftLeft|ShiftRight|ControlLeft|ControlRight|AltLeft|AltRight|Enter|Tab|Backspace|Mouse[0-2]|[A-Za-z]+)$/.test(p.bindings[k]))&&new Set(Object.values(p.bindings)).size===Object.keys(bindings).length)Object.assign(bindings,p.bindings);const vol=(v,d)=>Number.isFinite(v)?Math.min(100,Math.max(0,v)):d;return {bindings,master:vol(p.master,100),music:vol(p.music,70),effects:vol(p.effects,100),muted:!!p.muted,timeOfDay:p.timeOfDay==='night'?'night':'day'}}
export function assignBinding(bindings,action,code){const other=Object.keys(bindings).find(k=>k!==action&&bindings[k]===code);if(other)bindings[other]=bindings[action];bindings[action]=code;return other}
